class Solution:
    def decodeString(self, s: str) -> str:
        def parse(i):
            out = []
            while i < len(s) and s[i] != ']':
                if s[i].isdigit():
                    count = 0
                    while i < len(s) and s[i].isdigit():
                        count = count * 10 + int(s[i])
                        i += 1
                    i += 1
                    inner, i = parse(i)
                    out.append(inner * count)
                    i += 1
                else:
                    out.append(s[i])
                    i += 1
            return "".join(out), i
        decoded, _ = parse(0)
        return decoded

solutions.better:
class Solution:
    def decodeString(self, s: str) -> str:
        count_stack = []
        string_stack = []
        current = []
        count = 0
        for ch in s:
            if ch.isdigit():
                count = count * 10 + int(ch)
            elif ch == '[':
                count_stack.append(count)
                string_stack.append(current)
                current = []
                count = 0
            elif ch == ']':
                repeat = count_stack.pop()
                previous = string_stack.pop()
                current = previous + current * repeat
            else:
                current.append(ch)
        return "".join(current)

