class Solution:
    def decodeString(self, s: str) -> str:
        stack = []
        for ch in s:
            if ch != ']':
                stack.append(ch)
            else:
                segment = []
                while stack and stack[-1] != '[':
                    segment.append(stack.pop())
                stack.pop()
                multiplier = 0
                base = 1
                while stack and stack[-1].isdigit():
                    multiplier += (ord(stack.pop()) - ord('0')) * base
                    base *= 10
                stack.append("".join(reversed(segment)) * multiplier)
        return "".join(stack)

